using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Preserve "Discriminator" property name for existing documents
        // (EF Core 9 defaults to "$type")
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Preserve old compound id format "Blog|1" for existing documents
        // (EF Core 9 defaults to key-only id)
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

        // Fix 3: HasIndex removed — throws InvalidOperationException in EF Core 9 Cosmos.
        // Manage indexing via the Azure Portal or Bicep/Terraform indexing policy instead.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name);  // REMOVED
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

arguments.old_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

arguments.new_str:
class SyncJob
{
    // Fix 4: Sync I/O (ToList, SaveChanges) throws in EF Core 9 Cosmos.
    // Must use async equivalents.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

